<template>
	<FrappeUIProvider>
		<!-- Transisi fade halus antar halaman (mode out-in: lama memudar dulu, baru muncul). -->
		<router-view v-slot="{ Component }">
			<transition name="page-fade" mode="out-in">
				<component :is="Component" />
			</transition>
		</router-view>
		<!-- Overlay PDF in-app (aktif saat lampiran PDF dibuka di aplikasi native). -->
		<PdfViewer />
		<!-- Overlay gambar in-app (lampiran gambar, agar tak pindah ke Safari). -->
		<AttachmentImageViewer />
		<!-- Notifikasi global (error/sukses/info) — selalu di atas semua konten. -->
		<Toasts />
		<!-- Layar "tidak ada koneksi" (C3): tampil penuh saat perangkat offline. -->
		<OfflineScreen />
	</FrappeUIProvider>
</template>

<script setup>
import { watch } from 'vue'
import { FrappeUIProvider } from 'frappe-ui'
import PdfViewer from './components/PdfViewer.vue'
import AttachmentImageViewer from './components/AttachmentImageViewer.vue'
import Toasts from './components/Toasts.vue'
import OfflineScreen from './components/OfflineScreen.vue'
import { session } from './data/session'
import { loadMyRoles, resetMyRoles } from './data/user'

// Fetch role asli user setiap kali transisi ke logged-in; reset saat logout.
watch(
	() => session.isLoggedIn,
	(isLoggedIn) => {
		if (isLoggedIn) {
			loadMyRoles()
		} else {
			resetMyRoles()
		}
	},
	{ immediate: true }
)
</script>
