/**
 * Pemilih gambar yang membawa tanggal berkas dari perangkat (aplikasi native).
 *
 * Input berkas biasa di WebView hanya memberi satu waktu, yaitu waktu ubah
 * (`File.lastModified`). Tanggal pembuatan tidak ikut terkirim. Plugin native
 * `FileMeta` membaca keduanya langsung dari penyimpanan perangkat, sama seperti
 * yang ditampilkan file manager.
 *
 * Di browser biasa plugin ini tidak ada, sehingga pemanggilnya tetap memakai
 * input berkas seperti sebelumnya.
 */

function plugin() {
	return (typeof window !== 'undefined' && window.Capacitor?.Plugins?.FileMeta) || null
}

/** True bila pemilih gambar bawaan aplikasi tersedia. */
export function bisaAmbilTanggalBerkas() {
	return !!plugin()?.pickImage
}

function keBlob(base64, mimeType) {
	const biner = atob(base64)
	const buf = new Uint8Array(biner.length)
	for (let i = 0; i < biner.length; i++) buf[i] = biner.charCodeAt(i)
	return new Blob([buf], { type: mimeType || 'image/jpeg' })
}

/**
 * Buka galeri lewat plugin native.
 *
 * Return null bila dibatalkan, atau objek:
 *   { file, tanggalDibuat, tanggalDiubah }
 * `file` berupa File biasa sehingga alur unggah yang sudah ada tetap dipakai.
 */
export async function pilihGambarDenganTanggal() {
	const p = plugin()
	if (!p?.pickImage) return null

	const hasil = await p.pickImage()
	if (!hasil || hasil.dibatalkan || !hasil.data) return null

	const nama = hasil.name || 'bukti-transfer.jpg'
	const blob = keBlob(hasil.data, hasil.mimeType)
	const file = new File([blob], nama, { type: blob.type })

	// Tanggal dibuat: waktu foto diambil bila ada, jika tidak waktu berkas
	// masuk ke penyimpanan perangkat.
	const tanggalDibuat = hasil.dateTaken || hasil.dateAdded || ''
	// Tanggal diubah: kolom milik galeri, atau milik penyimpanan dokumen.
	const tanggalDiubah = hasil.dateModified || hasil.lastModified || ''

	return { file, tanggalDibuat, tanggalDiubah }
}
