				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="actionsOpen"
							class="w-full max-w-screen-sm rounded-t-3xl bg-white px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl"
						>
							<div class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-gray-300" />
							<h2 class="mb-4 text-center text-base font-semibold text-gray-900">
								Action
							</h2>

							<p
								v-if="!adaAksi"
								class="py-3 text-center text-sm text-gray-400"
							>
								Tidak ada aksi tersedia untuk Anda.
							</p>
							<div v-else class="max-h-[55vh] space-y-2 overflow-y-auto px-0.5">
								<button
									v-for="a in d.actions"
									:key="a.action"
									type="button"
									:disabled="!!applying"
									class="flex w-full items-center justify-between gap-2 rounded-2xl border px-4 py-3.5 text-left transition disabled:opacity-50"
									:class="
										merah(a.action)
											? 'border-red-200 hover:border-red-400 hover:bg-red-50'
											: 'border-gray-200 hover:border-primary hover:bg-primary/5'
									"
									@click="pilihAksi(a)"
								>
									<span
										class="text-sm font-semibold"
										:class="merah(a.action) ? 'text-red-600' : 'text-gray-800'"
