<template>
	<!-- Tumpukan notifikasi global. Di-Teleport ke body supaya selalu di atas
	     konten/overlay mana pun. Muncul dari ATAS (turun dari bawah status bar). -->
	<Teleport to="body">
		<div
			class="pointer-events-none fixed inset-x-0 z-[9999] flex flex-col items-center gap-2 px-3"
			style="top: calc(1rem + env(safe-area-inset-top))"
		>
			<TransitionGroup
				enter-active-class="transition duration-200 ease-out"
				enter-from-class="-translate-y-3 opacity-0"
				leave-active-class="transition duration-150 ease-in"
				leave-to-class="-translate-y-2 opacity-0"
				move-class="transition duration-200"
			>
				<div
					v-for="t in toasts"
					:key="t.id"
					class="pointer-events-auto flex w-full max-w-screen-sm items-start gap-3 rounded-2xl border px-4 py-3 shadow-lg"
					:class="cardClass(t.type)"
					role="alert"
				>
					<!-- Ikon per tipe -->
					<span class="mt-0.5 shrink-0" :class="iconColor(t.type)">
						<svg
							v-if="t.type === 'error'"
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-5 w-5"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<circle cx="12" cy="12" r="10" />
							<path d="M12 8v4" />
							<path d="M12 16h.01" />
						</svg>
						<svg
							v-else-if="t.type === 'success'"
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-5 w-5"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" />
							<path d="m9 11 3 3L22 4" />
						</svg>
						<svg
							v-else
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-5 w-5"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<circle cx="12" cy="12" r="10" />
							<path d="M12 16v-4" />
							<path d="M12 8h.01" />
						</svg>
					</span>

					<div class="min-w-0 flex-1">
						<p
							v-if="t.title"
							class="text-sm font-semibold"
							:class="titleColor(t.type)"
						>
							{{ t.title }}
						</p>
						<p
							v-if="t.message"
							class="whitespace-pre-line break-words text-sm"
							:class="msgColor(t.type)"
						>
							{{ t.message }}
						</p>
					</div>

					<button
						type="button"
						class="-mr-1 shrink-0 rounded-md p-1 opacity-60 transition hover:opacity-100"
						:class="titleColor(t.type)"
						aria-label="Tutup"
						@click="dismissToast(t.id)"
					>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-4 w-4"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M18 6 6 18M6 6l12 12" />
						</svg>
					</button>
				</div>
			</TransitionGroup>
		</div>
	</Teleport>
</template>

<script setup>
import { toasts, dismissToast } from '../composables/toast'

function cardClass(type) {
	if (type === 'error') return 'border-red-200 bg-red-50'
	if (type === 'success') return 'border-green-200 bg-green-50'
	return 'border-blue-200 bg-blue-50'
}
function iconColor(type) {
	if (type === 'error') return 'text-red-500'
	if (type === 'success') return 'text-green-500'
	return 'text-blue-500'
}
function titleColor(type) {
	if (type === 'error') return 'text-red-800'
	if (type === 'success') return 'text-green-800'
	return 'text-blue-800'
}
function msgColor(type) {
	if (type === 'error') return 'text-red-700'
	if (type === 'success') return 'text-green-700'
	return 'text-blue-700'
}
</script>
